import{_ as n,a0 as l,w as r,s as o,I as e,x as t,a1 as p,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何將樹莓派配置為打印服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何將樹莓派配置為打印服務器 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何將樹莓派配置為打印服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何將樹莓派配置為打印服務器 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180308 How to set up a print server on a Raspberry Pi","title":"如何將樹莓派配置為打印服務器","tag":"201805","desc":""},"relativePath":"201805/20180308 How to set up a print server on a Raspberry Pi.md","filePath":"[post].md"}'),u={name:"201805/20180308 How to set up a print server on a Raspberry Pi.md"};function g(m,s,b,f,h,k){const i=l("Link");return r(),o("div",null,[s[19]||(s[19]=e("h1",{id:"如何將樹莓派配置為打印服務器",tabindex:"-1"},[t("如何將樹莓派配置為打印服務器 "),e("a",{class:"header-anchor",href:"#如何將樹莓派配置為打印服務器","aria-label":"Permalink to “如何將樹莓派配置為打印服務器”"},"​")],-1)),s[20]||(s[20]=e("blockquote",null,[e("p",null,"用樹莓派和 CUPS 打印服務器將你的打印機變成網絡打印機。")],-1)),s[21]||(s[21]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/life-raspberrypi_0.png?itok=Kczz87J2",alt:""})],-1)),e("p",null,[s[1]||(s[1]=t("我喜歡在家做一些小項目，因此，今年我買了一個 ",-1)),p(i,{href:"https://www.raspberrypi.org/products/raspberry-pi-3-model-b/"},{default:a(()=>[...s[0]||(s[0]=[t("樹莓派 3 Model B",-1)])]),_:1}),s[2]||(s[2]=t("，這是一個非常適合像我這樣的業餘愛好者的東西。使用樹莓派 3 Model B 的內置無線功能，我可以不使用線纜就將樹莓派連接到我的家庭網絡中。這樣可以很容易地將樹莓派用到各種所需要的地方。",-1))]),s[22]||(s[22]=e("p",null,"在家裏，我和我的妻子都使用筆記本電腦，但是我們只有一台打印機：一台使用的並不頻繁的 HP 彩色激光打印機。因為我們的打印機並不內置無線網卡，因此，它不能直接連接到無線網絡中，我們一般把打印機連接到我的筆記本電腦上，因為通常是我在打印。雖然這種安排在大多數時間都沒有問題，但是，有時候，我的妻子想在不 “麻煩” 我的情況下，自己去打印一些東西。",-1)),s[23]||(s[23]=e("p",null,"我覺得我們需要一個將打印機連接到無線網絡的解決方案，以便於我們都能夠隨時隨地打印。我本想買一個無線打印服務器將我的 USB 打印機連接到家裏的無線網絡上。後來，我決定使用我的樹莓派，將它設置為打印服務器，這樣就可以讓家裏的每個人都可以隨時來打印。",-1)),s[24]||(s[24]=e("h3",{id:"基本設置",tabindex:"-1"},[t("基本設置 "),e("a",{class:"header-anchor",href:"#基本設置","aria-label":"Permalink to “基本設置”"},"​")],-1)),e("p",null,[s[4]||(s[4]=t("設置樹莓派是非常簡單的事。我下載了 ",-1)),p(i,{href:"https://www.raspberrypi.org/downloads/"},{default:a(()=>[...s[3]||(s[3]=[t("Raspbian",-1)])]),_:1}),s[5]||(s[5]=t(" 鏡像，並將它寫入到我的 microSD 卡中。然後，使用它來引導一個連接了 HDMI 顯示器、 USB 鍵盤和 USB 鼠標的樹莓派。之後，我們開始對它進行設置！",-1))]),s[25]||(s[25]=d(`<p>這個樹莓派系統自動引導到一個圖形桌面，然後我做了一些基本設置：設置鍵盤語言、連接無線網絡、設置普通用户帳户（<code>pi</code>）的密碼、設置管理員用户（<code>root</code>）的密碼。</p><p>我並不打算將樹莓派運行在桌面環境下。我一般是通過我的普通的 Linux 計算機遠程來使用它。因此，我使用樹莓派的圖形化管理工具，去設置將樹莓派引導到控制台模式，但不以 <code>pi</code> 用户自動登入。</p><p>重新啓動樹莓派之後，我需要做一些其它的系統方面的小調整，以便於我在家用網絡中使用樹莓派做為 “服務器”。我設置它的 DHCP 客户端為使用靜態 IP 地址；默認情況下，DHCP 客户端可能任選一個可用的網絡地址，這樣我會不知道應該用哪個地址連接到樹莓派。我的家用網絡使用一個私有的 A 類地址，因此，我的路由器的 IP 地址是 <code>10.0.0.1</code>，並且我的全部可用地 IP 地址是 <code>10.0.0.x</code>。在我的案例中，低位的 IP 地址是安全的，因此，我通過在 <code>/etc/dhcpcd.conf</code> 中添加如下的行，設置它的無線網絡使用 <code>10.0.0.11</code> 這個靜態地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>interface wlan0</span></span>
<span class="line"><span>static ip_address=10.0.0.11/24</span></span>
<span class="line"><span>static routers=10.0.0.1</span></span>
<span class="line"><span>static domain_name_servers=8.8.8.8 8.8.4.4</span></span></code></pre></div><p>在我再次重啓之前，我需要去確認安全 shell 守護程序（SSHD）已經正常運行（你可以在 “偏好” 中設置哪些服務在引導時啓動它）。這樣我就可以使用 SSH 從普通的 Linux 系統上基於網絡連接到樹莓派中。</p><h3 id="打印設置" tabindex="-1">打印設置 <a class="header-anchor" href="#打印設置" aria-label="Permalink to “打印設置”">​</a></h3><p>現在，我的樹莓派已經連到網絡上了，我通過 SSH 從我的 Linux 電腦上遠程連接它，接着做剩餘的設置。在繼續設置之前，確保你的打印機已經連接到樹莓派上。</p><p>設置打印機很容易。現代的打印服務器被稱為 CUPS，意即“通用 Unix 打印系統”。任何最新的 Unix 系統都可以通過 CUPS 打印服務器來打印。為了在樹莓派上設置 CUPS 打印服務器。你需要通過幾個命令去安裝 CUPS 軟件，並使用新的配置來重啓打印服務器，這樣就可以允許其它系統來打印了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install cups</span></span>
<span class="line"><span>$ sudo cupsctl --remote-any</span></span>
<span class="line"><span>$ sudo /etc/init.d/cups restart</span></span></code></pre></div><p>在 CUPS 中設置打印機也是非常簡單的，你可以通過一個 Web 界面來完成。CUPS 監聽端口是 631，因此你用常用的瀏覽器來訪問這個地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://10.0.0.11:631/</span></span></code></pre></div><p>你的 Web 瀏覽器可能會彈出警告，因為它不認可這個 Web 瀏覽器的 https 證書；選擇 “接受它”，然後以管理員用户登入系統，你將看到如下的標準的 CUPS 面板：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/cups-1-home.png?itok=t9OFJgSX" alt=""></p><p>這時候，導航到管理標籤，選擇 “Add Printer”。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/cups-2-administration.png?itok=MlEINoYC" alt=""></p><p>如果打印機已經通過 USB 連接，你只需要簡單地選擇這個打印機和型號。不要忘記去勾選共享這個打印機的選擇框，因為其它人也要使用它。現在，你的打印機已經在 CUPS 中設置好了。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/cups-3-printer.png?itok=N5upmhE7" alt=""></p><h3 id="客户端設置" tabindex="-1">客户端設置 <a class="header-anchor" href="#客户端設置" aria-label="Permalink to “客户端設置”">​</a></h3><p>從 Linux 中設置一台網絡打印機非常簡單。我的桌面環境是 GNOME，你可以從 GNOME 的“設置”應用程序中添加網絡打印機。只需要導航到“設備和打印機”，然後解鎖這個面板。點擊 “添加” 按鈕去添加打印機。</p><p>在我的系統中，GNOME 的“設置”應用程序會自動發現網絡打印機並添加它。如果你的系統不是這樣，你需要通過樹莓派的 IP 地址，手動去添加打印機。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/gnome-settings-printers.png?itok=NOQLTaLs" alt=""></p><p>設置到此為止！我們現在已經可以通過家中的無線網絡來使用這台打印機了。我不再需要物理連接到這台打印機了，家裏的任何人都可以使用它了！</p><hr>`,23)),e("p",null,[s[7]||(s[7]=t("via: ",-1)),p(i,{href:"https://opensource.com/article/18/3/print-server-raspberry-pi"},{default:a(()=>[...s[6]||(s[6]=[t("https://opensource.com/article/18/3/print-server-raspberry-pi",-1)])]),_:1})]),e("p",null,[s[11]||(s[11]=t("作者：",-1)),p(i,{href:"https://opensource.com/users/jim-hall"},{default:a(()=>[...s[8]||(s[8]=[t("Jim Hall",-1)])]),_:1}),s[12]||(s[12]=t(" 譯者：",-1)),p(i,{href:"https://github.com/qhwdw"},{default:a(()=>[...s[9]||(s[9]=[t("qhwdw",-1)])]),_:1}),s[13]||(s[13]=t(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:a(()=>[...s[10]||(s[10]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[16]||(s[16]=t("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[14]||(s[14]=[t("LCTT",-1)])]),_:1}),s[17]||(s[17]=t(" 原創編譯，",-1)),p(i,{href:"https://linux.cn/"},{default:a(()=>[...s[15]||(s[15]=[t("Linux中國",-1)])]),_:1}),s[18]||(s[18]=t(" 榮譽推出",-1))])])}const x=n(u,[["render",g]]);export{P as __pageData,x as default};
